import React, { useState, useEffect } from 'react';
import { BrowserRouter as Router, Routes, Route, Link } from 'react-router-dom';
import axios from 'axios';
import './App.css';

// Components
import Dashboard from './pages/Dashboard';
import UsersPage from './pages/Users';
import RidesPage from './pages/Rides';
import DriversPage from './pages/Drivers';
import WalletPage from './pages/Wallet';
import AnalyticsPage from './pages/Analytics';

function App() {
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');

  const handleLogin = (e) => {
    e.preventDefault();
    // Simple hardcoded credentials for demo
    if (email === 'admin@gocab.com' && password === 'admin123') {
      setIsAuthenticated(true);
      setError('');
      localStorage.setItem('adminToken', 'authenticated');
    } else {
      setError('Invalid email or password');
    }
  };

  const handleLogout = () => {
    setIsAuthenticated(false);
    setEmail('');
    setPassword('');
    localStorage.removeItem('adminToken');
  };

  return (
    <Router>
      <div className="app">
        {isAuthenticated ? (
          <>
            <nav className="sidebar">
              <div className="logo">
                <h2>🚕 GoCab Admin</h2>
              </div>
              <ul className="nav-links">
                <li><Link to="/">Dashboard</Link></li>
                <li><Link to="/users">Users</Link></li>
                <li><Link to="/drivers">Drivers</Link></li>
                <li><Link to="/rides">Rides</Link></li>
                <li><Link to="/wallet">Wallet</Link></li>
                <li><Link to="/analytics">Analytics</Link></li>
                <li><button onClick={handleLogout} style={{width: '100%', textAlign: 'left', background: 'none', border: 'none', color: 'inherit', cursor: 'pointer', padding: '10px'}}>Logout</button></li>
              </ul>
            </nav>

            <main className="main-content">
              <Routes>
                <Route path="/" element={<Dashboard />} />
                <Route path="/users" element={<UsersPage />} />
                <Route path="/drivers" element={<DriversPage />} />
                <Route path="/rides" element={<RidesPage />} />
                <Route path="/wallet" element={<WalletPage />} />
                <Route path="/analytics" element={<AnalyticsPage />} />
              </Routes>
            </main>
          </>
        ) : (
          <div className="login-container">
            <div className="login-box">
              <h2>Admin Login</h2>
              <form onSubmit={handleLogin}>
                <input 
                  type="email" 
                  placeholder="Email" 
                  value={email}
                  onChange={(e) => setEmail(e.target.value)}
                  required
                />
                <input 
                  type="password" 
                  placeholder="Password" 
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                  required
                />
                {error && <p style={{color: 'red', textAlign: 'center'}}>{error}</p>}
                <button type="submit">Login</button>
              </form>
              <p style={{marginTop: '20px', textAlign: 'center', fontSize: '12px', color: '#666'}}>
                Demo: admin@gocab.com / admin123
              </p>
            </div>
          </div>
        )}
      </div>
    </Router>
  );
}

export default App;